import {$,esc,showToast} from "./dom.js";
import {appState,events,products,productSources,placeholders,supportedLanguages} from "./state.js";
import {openLanguageDrawer} from "./language-editor.js";
import {renderAnnotations} from "./annotations.js";

const steps=[[1,"触发与接收者","来源与设备绑定用户"],[2,"投递与生命周期","模式、窗口与发布校验"],[3,"基础信息与消息","内容、多语言、跳转"]];
const product=()=>products.find(x=>x.id===appState.selectedProductId)||products[0];
const sources=()=>productSources[appState.selectedProductId]||{properties:[],countdowns:[],consumables:[]};
const mode=()=>appState.rule.reminderMode;
const currentMessage=()=>mode()==="stateSwitch"?appState.message.stateValues[appState.activeMessageState]["en-US"]:appState.message.values["en-US"];
const selectedEvent=()=>events.find(e=>e.id===appState.rule.eventId&&e.productId===appState.selectedProductId);

function tokenDisabled(token){
  if(token.includes("Consumable")) return appState.rule.triggerType!=="consumable";
  if(token==="${cozyCountdownTimer}") return appState.rule.triggerType!=="cloud";
  return false;
}
function tokenPanel(field,stateful=false){return `<div class="placeholder-panel">${placeholders.map(p=>`<button type="button" class="placeholder ${tokenDisabled(p.token)?"is-disabled":""}" data-token="${esc(p.token)}" data-message-field="${field}" data-stateful="${stateful}" ${tokenDisabled(p.token)?"disabled":""}>${esc(p.token)}</button>`).join("")}</div><p class="form-help">点击插入光标位置；不可解析变量置灰，未知变量在发布时阻断。</p>`}
function stepNav(){return `<nav class="step-nav" id="ruleStepNav" data-anchor="step-nav"><div class="step-progress"><span>规则配置流程</span><strong>步骤 ${appState.ruleStep} / 3</strong></div><ol class="step-list">${steps.map(([n,t,s],i)=>`<li class="step-slot"><button class="step-item ${n===appState.ruleStep?"active":""} ${n<appState.ruleStep?"is-complete":""}" data-step="${n}"><span class="step-index">${n<appState.ruleStep?"✓":n}</span><span class="step-copy"><strong>${t}</strong><small>${s}</small></span></button>${i<2?'<span class="step-connector"></span>':""}</li>`).join("")}</ol></nav>`}

function basic(){
  const p=product(),r=appState.rule,stateful=mode()==="stateSwitch",msg=stateful?appState.message.stateValues[appState.activeMessageState]["en-US"]:appState.message.values["en-US"];
  const langs=appState.selectedLocales.map(c=>supportedLanguages.find(x=>x[0]===c)?.[1]).join("、");
  return `<div class="form-section"><div class="section-title"><h3>基础信息</h3><p>产品上下文已锁定</p></div><div class="form-grid"><label class="form-row full"><span class="form-label"><i class="required">*</i>规则名称</span><input class="el-input" data-rule="name" value="${esc(r.name)}"></label><label class="form-row"><span class="form-label">当前产品</span><div class="readonly-field">${esc(p.name)} · ${esc(p.id)}</div></label><label class="form-row"><span class="form-label">消息分类</span><select class="el-select" data-rule="category">${["安全","维护","耗材","系统","通知"].map(x=>`<option ${x===r.category?"selected":""}>${x}</option>`).join("")}</select></label></div></div><div class="form-section" data-anchor="message-editor"><div class="section-title"><h3>推送消息</h3><p>默认语言 English；已选 ${appState.selectedLocales.length}/18</p></div>${stateful?`<div class="help-alert warning">状态切换提醒分别保存开启/关闭消息。初始化为「${r.initialState==="on"?"开启":"关闭"}」，窗口结束只推送最终状态。</div><div class="state-message-tabs"><button class="${appState.activeMessageState==="on"?"active":""}" data-message-state="on">开启时消息</button><button class="${appState.activeMessageState==="off"?"active":""}" data-message-state="off">关闭时消息</button></div>`:""}<label class="form-row full"><span class="form-label"><i class="required">*</i>Title · English${stateful?` · ${appState.activeMessageState==="on"?"开启":"关闭"}`:""}</span><input class="el-input" data-content="title" value="${esc(msg.title)}" maxlength="100">${tokenPanel("title",stateful)}</label><label class="form-row full"><span class="form-label"><i class="required">*</i>Body · English${stateful?` · ${appState.activeMessageState==="on"?"开启":"关闭"}`:""}</span><textarea class="el-textarea" data-content="body" maxlength="200">${esc(msg.body)}</textarea>${tokenPanel("body",stateful)}</label><div class="form-row full" data-anchor="jump-mode"><span class="form-label">跳转页面</span><div class="radio-row">${[["none","不跳转"],["preset","产品预设页面"],["custom","自定义 cozy:// 深链"]].map(([v,t])=>`<label class="choice-card ${appState.message.cozyLinkMode===v?"selected":""}"><input type="radio" name="link" value="${v}" ${appState.message.cozyLinkMode===v?"checked":""}><span class="choice-copy"><strong>${t}</strong><small>${v==="custom"?"仅接受 cozy://":""}</small></span></label>`).join("")}</div>${appState.message.cozyLinkMode==="preset"?`<select class="el-select" data-preset>${p.presetLinks.map(x=>`<option value="${x.id}" ${x.id===appState.message.presetLinkId?"selected":""}>${x.label} · ${x.uri}</option>`).join("")}</select>`:""}${appState.message.cozyLinkMode==="custom"?`<input class="el-input" data-link value="${esc(appState.message.cozyLink)}" placeholder="cozy://device/{deviceId}/home">`:""}</div><div class="help-alert success">已选语言：${esc(langs)}。未勾选语言在 KV 矩阵中隐藏，草稿保留且不参与校验。</div><button class="el-btn" data-language>编辑 18 语言 KV 矩阵</button></div>`;
}

function sourceCapability(source,kind){
  if(!source)return `<div class="help-alert warning">当前产品暂无可用${kind}来源。</div>`;
  const ready=source.deviceCapability==="verified"&&(kind!=="云计时器"||source.cycleContract==="verified");
  return `<div class="help-alert ${ready?"success":"warning"}"><strong>${ready?"可发布":"待来源验收"}</strong> · ${kind}必须能提供真实 deviceId${kind==="云计时器"?"、timerInstanceId 与 cycleId/resetGeneration":""}；未验证不可发布，运行时失败将拒绝入队并审计。</div>`;
}

function trigger(){
  const r=appState.rule,s=sources(),selected=s.properties.find(x=>x.id===r.propertyId)||s.properties[0];
  const choices=[["device","设备触发","属性满足条件时触发"],["cloud","云端触发","每个计时周期到 0 触发一次"],["consumable","耗材触发","不足或耗尽时触发"],["event","事件触发","使用当前产品 webhook 事件"]];
  let detail="";
  if(r.triggerType==="device") detail=`<div class="form-grid"><label class="form-row"><span class="form-label"><i class="required">*</i>设备属性</span><select class="el-select" data-rule="propertyId">${s.properties.map(x=>`<option value="${x.id}" ${x.id===r.propertyId?"selected":""}>${x.name}${x.unit?`（${x.unit}）`:""}</option>`).join("")}</select></label><label class="form-row"><span class="form-label"><i class="required">*</i>运算符</span><select class="el-select" data-rule="operator">${(selected?.operators||[]).map(x=>`<option ${x===r.operator?"selected":""}>${x}</option>`).join("")}</select></label><label class="form-row full"><span class="form-label"><i class="required">*</i>条件值</span>${selected?.type==="enum"?`<select class="el-select" data-rule="propertyValue">${selected.options.map(x=>`<option ${x===r.propertyValue?"selected":""}>${x}</option>`).join("")}</select>`:selected?.type==="boolean"?`<select class="el-select" data-rule="propertyValue"><option>true</option><option>false</option></select>`:`<input class="el-input" data-rule="propertyValue" value="${esc(r.propertyValue)}" placeholder="例如 ${selected?.example||"1"}">`}<p class="form-help">触发逻辑：if（${esc(selected?.name||"属性")} ${esc(r.operator)} ${esc(r.propertyValue)}${selected?.unit?` ${selected.unit}`:""}）。</p></label></div>`;
  if(r.triggerType==="cloud") {const timer=s.countdowns.find(x=>x.id===r.cloudCountdownId)||s.countdowns[0];detail=`<div class="form-grid"><label class="form-row"><span class="form-label"><i class="required">*</i>云计时器</span><select class="el-select" data-rule="cloudCountdownId">${s.countdowns.map(x=>`<option value="${x.id}" ${x.id===r.cloudCountdownId?"selected":""}>${x.name}</option>`).join("")||'<option value="">当前产品暂无云计时器</option>'}</select></label><label class="form-row"><span class="form-label">触发条件</span><div class="readonly-field">剩余时长 ≤ 阈值（阈值固定 0 分钟）</div></label></div><div class="timeline" data-anchor="cloud-cycle"><div class="timeline-title">云计时器周期：timerCycleCompleted</div><div class="timeline-row"><span class="timeline-dot active"></span><strong>倒计时运行</strong><small>剩余时长 ≤ 0</small><span>到 0 → 触发一次 → 自动 reset → 下一周期</span></div><div class="cycle-meta"><code>${esc(timer?.timerInstanceId||"timerInstanceId 待验收")}</code> · <code>${esc(timer?.cycleId||"cycleId 待验收")}</code></div><div class="webhook-actions"><button type="button" class="el-btn el-btn--small" data-cycle-trigger>模拟到 0</button><button type="button" class="el-btn el-btn--small" data-cycle-replay>重复同一 occurrence</button></div></div><p class="form-help">数据来源：产品高级配置 &gt; 云倒计时。每个周期到 0 只触发一次；同一 occurrence 重复上报不会入队。</p>${sourceCapability(timer,"云计时器")}`;}
  if(r.triggerType==="consumable") {const consumable=s.consumables.find(x=>x.id===r.consumableId);detail=`<div class="form-grid"><label class="form-row"><span class="form-label"><i class="required">*</i>耗材项</span><select class="el-select" data-rule="consumableId">${s.consumables.map(x=>`<option value="${x.id}" ${x.id===r.consumableId?"selected":""}>${x.name}</option>`).join("")||'<option value="">当前产品暂无配置耗材</option>'}</select></label><label class="form-row"><span class="form-label"><i class="required">*</i>触发项</span><select class="el-select" data-rule="consumableEvent"><option value="low" ${r.consumableEvent==="low"?"selected":""}>不足</option><option value="empty" ${r.consumableEvent==="empty"?"selected":""}>耗尽</option></select></label></div>${sourceCapability(consumable,"耗材")}`;}
  if(r.triggerType==="event") {const event=selectedEvent();detail=`<label class="form-row full"><span class="form-label"><i class="required">*</i>当前产品已发布事件</span><select class="el-select" data-rule="eventId">${events.filter(x=>x.productId===appState.selectedProductId&&x.status==="已发布").map(x=>`<option value="${x.id}" ${x.id===r.eventId?"selected":""}>${x.name} · ${x.eventType}</option>`).join("")||'<option value="">暂无已发布事件</option>'}</select></label><div class="webhook-box"><strong>Webhook 安全入口</strong><span>${esc(event?.webhookUrl||"发布事件后生成 webhook URL")}</span><small>${esc(event?.securityStatus||"待配置")} · 认证在规则引擎前完成；旧 Event Token 不再使用</small></div>`;}
  return `<div class="form-section" data-anchor="trigger-source"><div class="section-title"><h3>触发源</h3><p>选择一种来源</p></div><div class="radio-row">${choices.map(([v,t,d])=>`<label class="choice-card ${r.triggerType===v?"selected":""}"><input type="radio" name="trigger" value="${v}" ${r.triggerType===v?"checked":""}><span class="choice-copy"><strong>${t}</strong><small>${d}</small></span></label>`).join("")}</div><div class="trigger-detail">${detail}</div></div><div class="form-section" data-anchor="recipient-resolution"><div class="section-title"><h3>接收者解析</h3><p>围绕真实设备</p></div><div class="help-alert">固定规则：每次触发必须落到真实 <code>deviceId</code>，最终目标用户 = <code>BindUsers(deviceId)</code>。绑定用户为空时正常抑制并审计；本页面不提供外部用户集合、独立用户条件或 B 端接收人名单。</div></div>`;
}

function delivery(){
  const r=appState.rule,isState=mode()==="stateSwitch",needsWindow=mode()!=="each";
  const options=[["each","逐条发送","每个唯一事件立即发送；不设最小间隔"],["discard","后续丢弃","窗口首条立即发送，后续 suppressed"],["merge","合并发送（取最后一次）","首条立即，窗口末只发最后一次事件"],["stateSwitch","状态切换提醒","仅事件触发；窗口末发送最终开/关状态"]];
  const invalid=isState&&r.triggerType!=="event";
  return `<div class="form-section" data-anchor="priority-field"><div class="section-title"><h3>优先级</h3><p>只影响投递调度，不限制提醒模式</p></div><div class="radio-row">${[["P0","紧急"],["P1","重要"],["P2","普通"]].map(([v,t])=>`<label class="choice-card ${r.priority===v?"selected":""}"><input type="radio" name="priority" value="${v}" ${r.priority===v?"checked":""}><span class="choice-copy"><strong>${v} · ${t}</strong><small>与提醒模式独立</small></span></label>`).join("")}</div></div><div class="form-section" data-anchor="delivery-mode"><div class="section-title"><h3>提醒模式</h3><p>四选一；优先级不改变模式</p></div><div class="radio-row">${options.map(([v,t,d])=>`<label class="choice-card ${mode()===v?"selected":""} ${v==="stateSwitch"&&r.triggerType!=="event"?"disabled":""}"><input type="radio" name="mode" value="${v}" ${mode()===v?"checked":""} ${v==="stateSwitch"&&r.triggerType!=="event"?"disabled":""}><span class="choice-copy"><strong>${t}</strong><small>${d}</small></span></label>`).join("")}</div>${needsWindow?`<label class="form-row" style="margin-top:14px"><span class="form-label"><i class="required">*</i>最小发送间隔</span><input class="el-input" type="number" min="5" max="10080" data-rule="minIntervalMinutes" value="${r.minIntervalMinutes}"><p class="form-help">5 分钟至 7 天；discard/merge 从首条实际入队起固定窗口，stateSwitch 首个事件起固定窗口且不延长。</p></label>`:""}${isState?`<div class="form-row" style="margin-top:14px"><span class="form-label">事件初始化状态</span><div class="radio-row"><label><input type="radio" name="initial" value="off" ${r.initialState==="off"?"checked":""}> 关闭</label><label><input type="radio" name="initial" value="on" ${r.initialState==="on"?"checked":""}> 开启</label></div><p class="form-help">每个有效事件按 deviceId 原子翻转；开启/关闭分别使用步骤 1 的消息内容。</p></div>`:""}${invalid?'<div class="help-alert danger">状态切换提醒仅可用于事件触发。</div>':""}<div class="timeline" data-anchor="frequency-timeline"><div class="timeline-title">投递时间线演示</div><div class="timeline-row"><span class="timeline-dot active"></span><strong>首条事件</strong><small>立即入队</small><span>窗口开始，记录 occurrence</span></div><div class="timeline-row"><span class="timeline-dot"></span><strong>窗口内后续</strong><small>${mode()==="discard"?"suppressed":mode()==="merge"?"保留最后一次":"更新最终状态"}</small><span>不重复执行首条业务效果</span></div><div class="timeline-row"><span class="timeline-dot"></span><strong>窗口结束</strong><small>${isState?"最终 on/off":"按模式处理"}</small><span>${isState?"只发送最终状态内容":"合并模式仅发送最后事件内容"}</span></div></div></div><div class="form-section" data-anchor="validation"><div class="section-title"><h3>发布校验</h3><p>已选语言、来源能力与模式</p></div>${validation()}</div>`;
}

function validation(){
  const r=appState.rule,stateful=mode()==="stateSwitch",source=r.triggerType==="cloud"?sources().countdowns.find(x=>x.id===r.cloudCountdownId):r.triggerType==="consumable"?sources().consumables.find(x=>x.id===r.consumableId):null,event=selectedEvent(),property=sources().properties.find(x=>x.id===r.propertyId);
  const msgs=stateful?[appState.message.stateValues.on,appState.message.stateValues.off]:[appState.message.values];
  const contentOk=msgs.every(values=>appState.selectedLocales.every(c=>{const v=values[c]||{};return v.title?.trim()&&v.body?.trim()&&v.title.length<=100&&v.body.length<=200}));
  const deviceConditionOk=r.triggerType!=="device"||!!property&&property.operators.includes(r.operator)&&String(r.propertyValue||"").trim()!=="";
  const sourceOk=deviceConditionOk&&(!source||(source.deviceCapability==="verified"&&(r.triggerType!=="cloud"||source.cycleContract==="verified")));
  const eventOk=r.triggerType!=="event"||!!event&&event.status==="已发布"&&event.securityStatus==="已配置";
  const linkOk=appState.message.cozyLinkMode!=="custom"||(/^cozy:\/\/[^\s]+$/.test(appState.message.cozyLink)&&!appState.message.cozyLink.includes(" ")&&appState.message.cozyLink.length<=2048);
  const intervalOk=mode()==="each"||(+r.minIntervalMinutes>=5&&+r.minIntervalMinutes<=10080);
  const unknown=msgs.some(values=>appState.selectedLocales.some(c=>/\$\{([^}]+)\}/g.test(`${values[c]?.title||""} ${values[c]?.body||""}`)&&![...`${values[c]?.title||""} ${values[c]?.body||""}`.matchAll(/\$\{([^}]+)\}/g)].every(m=>placeholders.some(p=>p.token===m[0]))));
  const items=[[!!r.name,"规则名称"],[contentOk,stateful?"开启/关闭 × 已选语言内容":"已选语言 title/body"],[sourceOk,"设备条件 / 来源周期能力"],[eventOk,"Webhook 安全配置与事件发布状态"],[!unknown,"变量合法且可解析"],[linkOk,"cozy:// 跳转链接"],[!invalidState(stateful,r),"状态切换仅事件触发"],[intervalOk,"窗口最小发送间隔"]];
  return `<div class="validation-list">${items.map(([ok,t])=>`<div class="validation-item ${ok?"":"validation-fail"}"><span>${ok?"✓":"!"} ${t}</span><span class="el-tag el-tag--${ok?"success":"danger"} is-plain">${ok?"通过":"阻断"}</span></div>`).join("")}</div>`;
}
function invalidState(stateful,r){return stateful&&r.triggerType!=="event"}
function content(){return appState.ruleStep===1?trigger():appState.ruleStep===2?delivery():basic()}
function shell(){return `<div class="drawer-host is-open" id="ruleDrawer"><div class="drawer-mask" data-close></div><aside class="drawer"><header class="drawer-header"><div class="drawer-title"><h2>${appState.editingRule?"编辑":"新建"}推送规则</h2><p>${esc(product().name)} · 设备主体消息推送</p></div><button class="icon-btn" data-close>×</button></header><div class="drawer-main">${stepNav()}<div class="drawer-body"><section class="drawer-content" id="ruleStepContent">${content()}</section></div></div><footer class="drawer-footer"><span class="save-hint">自动保存上次编辑：刚刚</span><div class="footer-actions"><button class="el-btn" data-draft>保存草稿</button><button class="el-btn" data-prev ${appState.ruleStep===1?"disabled":""}>上一步</button>${appState.ruleStep<3?'<button class="el-btn el-btn--primary" data-next>下一步</button>':'<button class="el-btn el-btn--primary" data-publish>保存并启用</button>'}</div></footer></aside></div>`}
function rerender(){const host=$("#ruleDrawer");if(!host)return;host.outerHTML=shell();wire();renderAnnotations(`rule${appState.ruleStep}`,`规则配置 · 步骤 ${appState.ruleStep}/3`)}
function insertToken(el){const target=$("#ruleDrawer").querySelector(`[data-content="${el.dataset.messageField}"]`);if(!target)return;const obj=el.dataset.stateful==="true"?appState.message.stateValues[appState.activeMessageState]["en-US"]:appState.message.values["en-US"];const a=target.selectionStart??target.value.length;target.value=`${target.value.slice(0,a)}${el.dataset.token}${target.value.slice(target.selectionEnd??a)}`;obj[el.dataset.messageField]=target.value;target.focus();target.selectionStart=target.selectionEnd=a+el.dataset.token.length}
function wire(){
  const host=$("#ruleDrawer");
  host.querySelectorAll("[data-close]").forEach(x=>x.onclick=closeRuleDrawer);
  host.querySelectorAll("[data-step]").forEach(x=>x.onclick=()=>{appState.ruleStep=+x.dataset.step;rerender()});
  host.querySelectorAll("[data-rule]").forEach(x=>x.onchange=()=>{appState.rule[x.dataset.rule]=x.value;if(x.dataset.rule==="propertyId"){const next=sources().properties.find(p=>p.id===x.value);appState.rule.operator=next?.operators?.[0]||"=";appState.rule.propertyValue=next?.type==="enum"?next.options?.[0]||"":next?.type==="boolean"?"true":next?.example||""}rerender()});
  host.querySelectorAll("[data-content]").forEach(x=>x.oninput=()=>{(mode()==="stateSwitch"?appState.message.stateValues[appState.activeMessageState]["en-US"]:appState.message.values["en-US"])[x.dataset.content]=x.value});
  host.querySelectorAll("[data-token]").forEach(x=>x.onclick=()=>insertToken(x));
  host.querySelectorAll('input[name="trigger"]').forEach(x=>x.onchange=()=>{appState.rule.triggerType=x.value;if(x.value!=="event"&&mode()==="stateSwitch")appState.rule.reminderMode="each";rerender()});
  host.querySelector("[data-cycle-trigger]")?.addEventListener("click",()=>showToast("timerCycleCompleted 已接收：本周期执行 1 次，计时器自动 reset"));
  host.querySelector("[data-cycle-replay]")?.addEventListener("click",()=>showToast("重复 occurrence 已去重：不入队、不计数","error"));
  host.querySelectorAll('input[name="priority"]').forEach(x=>x.onchange=()=>{appState.rule.priority=x.value;rerender()});
  host.querySelectorAll('input[name="mode"]').forEach(x=>x.onchange=()=>{appState.rule.reminderMode=x.value;rerender()});
  host.querySelectorAll('input[name="initial"]').forEach(x=>x.onchange=()=>{appState.rule.initialState=x.value;rerender()});
  host.querySelectorAll('input[name="link"]').forEach(x=>x.onchange=()=>{appState.message.cozyLinkMode=x.value;rerender()});
  host.querySelectorAll("[data-preset]").forEach(x=>x.onchange=()=>{appState.message.presetLinkId=x.value;appState.message.cozyLink=product().presetLinks.find(p=>p.id===x.value)?.uri||""});
  host.querySelectorAll("[data-link]").forEach(x=>x.oninput=()=>appState.message.cozyLink=x.value);
  host.querySelectorAll("[data-message-state]").forEach(x=>x.onclick=()=>{appState.activeMessageState=x.dataset.messageState;rerender()});
  host.querySelector("[data-language]")?.addEventListener("click",()=>openLanguageDrawer({onClose:rerender}));
  host.querySelector("[data-prev]")?.addEventListener("click",()=>{appState.ruleStep--;rerender()});
  host.querySelector("[data-next]")?.addEventListener("click",()=>{appState.ruleStep++;rerender()});
  host.querySelector("[data-draft]")?.addEventListener("click",()=>showToast("规则草稿已保存"));
  host.querySelector("[data-publish]")?.addEventListener("click",()=>{if(host.querySelectorAll(".validation-fail").length){showToast("发布校验未通过，请完成阻断项","error");return}showToast("规则已保存并启用");closeRuleDrawer()});
}
export function openRuleDrawer({edit=false}={}){appState.editingRule=edit;appState.ruleStep=1;$("#overlayRoot").innerHTML=shell();wire();renderAnnotations("rule1","规则配置 · 步骤 1/3")}
export function closeRuleDrawer(){const h=$("#ruleDrawer");if(h)h.remove();renderAnnotations(appState.tab,appState.tab==="rules"?"推送规则列表":"事件管理")}
